// Theme Switcher
const themeSwitch = document.querySelector(".theme-switch");
const prefersDarkScheme = window.matchMedia("(prefers-color-scheme: dark)");

// Check for saved theme preference or use system preference
const currentTheme =
  localStorage.getItem("theme") ||
  (prefersDarkScheme.matches ? "dark" : "light");

// Apply theme on load
document.documentElement.setAttribute("data-theme", currentTheme);

// Toggle theme
themeSwitch.addEventListener("click", () => {
  const newTheme =
    document.documentElement.getAttribute("data-theme") === "dark"
      ? "light"
      : "dark";

  document.documentElement.setAttribute("data-theme", newTheme);
  localStorage.setItem("theme", newTheme);
});

// Scroll Animations
const observerOptions = {
  root: null,
  rootMargin: "0px",
  threshold: 0.1,
};

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add("visible");
    }
  });
}, observerOptions);

// Add fade-in class to elements and observe them
document
  .querySelectorAll(
    ".section-title, .education-card, .course-card, .skill-group, .project-card, .timeline-item, .contact-item, .testimonial-card, .award-card",
  )
  .forEach((element) => {
    element.classList.add("fade-in");
    observer.observe(element);
  });

// Typing Effect
const typingText = document.querySelector(".typing-text");
const text = "Omar Mahmoud";
let isDeleting = false;
let charIndex = 0;
let typingDelay = 100;
let deletingDelay = 50;
let endDelay = 2000;

function type() {
  const currentText = text.substring(0, charIndex);
  typingText.textContent = currentText;

  if (!isDeleting && charIndex < text.length) {
    // Typing
    charIndex++;
    typingDelay = 100;
  } else if (isDeleting && charIndex > 0) {
    // Deleting
    charIndex--;
    typingDelay = 50;
  } else if (charIndex === text.length) {
    // Pause at end
    isDeleting = true;
    typingDelay = endDelay;
  } else if (charIndex === 0) {
    // Start typing again
    isDeleting = false;
    typingDelay = 500;
  }

  setTimeout(type, typingDelay);
}
// Start typing effect when page loads
window.addEventListener("load", type);

// Loading Bar Functionality
const loadingOverlay = document.getElementById("loadingOverlay");
const loadingProgress = document.getElementById("loadingProgress");

// Simulate loading progress
let progress = 0;
const loadingInterval = setInterval(() => {
  progress += Math.random() * 15;
  if (progress > 90) {
    progress = 90; // Don't complete until everything is loaded
  }
  loadingProgress.style.width = progress + "%";
}, 100);

// Wait for all resources to load
window.addEventListener("load", () => {
  // Complete the progress bar
  loadingProgress.style.width = "100%";

  // Wait a bit for the animation, then hide
  setTimeout(() => {
    loadingOverlay.classList.add("hidden");
    // Remove from DOM after transition
    setTimeout(() => {
      loadingOverlay.style.display = "none";
      clearInterval(loadingInterval);
    }, 500);
  }, 1000);
});

// Fallback: Hide loading after maximum wait time (6 seconds)
setTimeout(() => {
  if (loadingOverlay && !loadingOverlay.classList.contains("hidden")) {
    loadingProgress.style.width = "100%";
    setTimeout(() => {
      loadingOverlay.classList.add("hidden");
      setTimeout(() => {
        loadingOverlay.style.display = "none";
        clearInterval(loadingInterval);
      }, 500);
    }, 1000);
  }
}, 6000);
